-- Model: lks_oa_task_timesheet_curr
-- Description: Current active record for LKS_OA_TASK_TIMESHEET using ROW_NUMBER()
-- Generated by: bv pipeline generate transform with custom template
-- Satellite Type: SAT_ON_LINK
-- Parent: link LNK_TASK_TIMESHEET

WITH RANKED_RECORDS AS (
SELECT
    LNK_TASK_TIMESHEET_HKEY,  -- hash key
    LOAD_DATE AS _CURRENT_ACTIVE_TIMESTAMP, -- used: LOAD_DATE
    -- Satellite Attributes
    ID           ,  -- is_business_key
    TIMESHEET_ID ,  -- is_business_key
    LOAD_DATE    ,  -- is_load_timestamp
    LOAD_CYCLE_ID,  -- is_load_cycle_id
    DELETE_FLAG     -- is_delete_flag
    ,
    ROW_NUMBER() OVER (
        PARTITION BY LNK_TASK_TIMESHEET_HKEY
        ORDER BY LOAD_DATE DESC
    ) AS row_num
FROM {{ source('eli_dv_rv', 'lks_oa_task_timesheet') }}
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RECORDS
WHERE row_num = 1
AND DELETE_FLAG = 'N'
